/*
 * A276792  First differences of A003146.
 * https://oeis.org/A276792
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(n) = A003146(n+1) - A003146(n). This is equivalent to a(n) = 7
 *            - t(n‑1)·(t(n‑1)+1)/2, where t(k) is the k‑th letter of the
 *            Tribonacci word generated by the morphism 0→01, 1→02, 2→0
 * Range:     u8 n <= 10608, u16 n <= 10608, u32 n <= 10608, u64 n <= 10608,
 *            u128 n <= 10608, big any n
 * Validated: standard, pass, 115 terms through n = 9544 (2026-11-03)
 * Helpers:   mem
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include "../utils/mem.h"

/* static cache of the Tribonacci word (0/1/2 values) */
static seq_t *trib_cache = NULL;   /* pointer to the cached sequence */
static idx_t  trib_size  = 0;      /* number of elements currently cached */

/* returns a(n) for any n >= 1, in any order of calls */
seq_t a(idx_t n)
{
    if (n == 0)                 /* offset is 1; undefined for n = 0 */
        return 0;

    idx_t idx = n - 1;          /* t(n‑1) is needed for a(n) */

    /* initialise the cache with the first letter if empty */
    if (trib_size == 0) {
        trib_cache = mem_new(seq_t, 1);
        trib_cache[0] = 0;
        trib_size   = 1;
    }

    /* grow the Tribonacci word until it contains the required index */
    while (idx >= trib_size) {
        size_t new_len = 0;
        for (idx_t i = 0; i < trib_size; ++i) {
            seq_t v = trib_cache[i];
            new_len += (v == 0 || v == 1) ? 2 : 1;
        }

        seq_t *new_seq = mem_new(seq_t, new_len);
        size_t pos = 0;
        for (idx_t i = 0; i < trib_size; ++i) {
            seq_t v = trib_cache[i];
            if (v == 0) {              /* 0 → 0 1 */
                new_seq[pos++] = 0;
                new_seq[pos++] = 1;
            } else if (v == 1) {        /* 1 → 0 2 */
                new_seq[pos++] = 0;
                new_seq[pos++] = 2;
            } else {                    /* 2 → 0 */
                new_seq[pos++] = 0;
            }
        }

        mem_free(trib_cache);
        trib_cache = new_seq;
        trib_size  = (idx_t)new_len;
    }

    seq_t tval = trib_cache[idx];                 /* t(n‑1) ∈ {0,1,2} */
    seq_t diff = tval * (tval + 1) / 2;           /* 0 → 0, 1 → 1, 2 → 3 */
    return 7 - diff;                              /* 7, 6, or 4 */
}
